SELECT SUM(sale_settled_amount) AS gross_sale_proxy
FROM zs_observe.flipkart_settlement
WHERE is_active = true;

SELECT SUM(settled_amount) AS net_settlement
FROM zs_observe.flipkart_settlement
WHERE is_active = true;

SELECT ABS(SUM(mp_fee)) / NULLIF(SUM(sale_settled_amount), 0) AS effective_fee_rate
FROM zs_observe.flipkart_settlement
WHERE is_active = true;

SELECT SUM(mp_fee) AS marketplace_fee_total
FROM zs_observe.flipkart_settlement
WHERE is_active = true;

SELECT SUM(total_tcs_amount) AS tcs_deducted
FROM zs_observe.flipkart_settlement
WHERE is_active = true;

SELECT SUM(total_tds_amount) AS tds_deducted
FROM zs_observe.flipkart_settlement
WHERE is_active = true;

SELECT SUM(gst_on_mp_fees) AS gst_on_marketplace_fees
FROM zs_observe.flipkart_settlement
WHERE is_active = true;

SELECT SUM(total_tax) AS total_tax_on_fee
FROM zs_observe.flipkart_commission
WHERE is_active = true;

SELECT SUM(protection_fund_settled_amount) AS protection_fund_settlement
FROM zs_observe.flipkart_settlement
WHERE is_active = true;
